from fastapi import APIRouter, Depends, HTTPException
from fastapi.responses import JSONResponse
from sqlalchemy.orm import Session
from backend.services.db import connect
from backend.services.calculations import net_worth, cashflow, emergency, goals
from backend.services.calculations import goal_probability
from backend.models import ActiveHoldings, Goals, DataHealth
from backend.schemas import NetWorthResponse, CashflowResponse, EmergencyResponse, GoalsResponse, DataHealthResponse

router = APIRouter()

@router.get("/overview/net-worth", response_model=NetWorthResponse)
def get_net_worth(db: Session = Depends(connect)):
    net_worth_data = net_worth(db)
    return JSONResponse(content={"state": "ok", "data": net_worth_data})

@router.get("/overview/cashflow", response_model=CashflowResponse)
def get_cashflow(db: Session = Depends(connect)):
    cashflow_data = cashflow(db)
    return JSONResponse(content={"state": "ok", "data": cashflow_data})

@router.get("/overview/emergency", response_model=EmergencyResponse)
def get_emergency(db: Session = Depends(connect)):
    emergency_data = emergency(db)
    return JSONResponse(content={"state": "ok", "data": emergency_data})

@router.get("/overview/goals", response_model=GoalsResponse)
def get_goals(db: Session = Depends(connect)):
    goals_data = goals(db)
    return JSONResponse(content={"state": "ok", "data": goals_data})

@router.get("/overview/data-health", response_model=DataHealthResponse)
def get_data_health(db: Session = Depends(connect)):
    data_health_data = DataHealth.get(db, id=1)
    if not data_health_data:
        raise HTTPException(status_code=404, detail="Data health not found")
    return JSONResponse(content={"state": "ok", "data": data_health_data})

@router.post("/overview/goals", response_model=GoalsResponse)
def create_goal(goal: Goals, db: Session = Depends(connect)):
    db_goal = Goals(**goal.dict())
    db.add(db_goal)
    db.commit()
    db.refresh(db_goal)
    return JSONResponse(content={"state": "ok", "data": db_goal})

@router.put("/overview/goals/{goal_id}", response_model=GoalsResponse)
def update_goal(goal_id: int, goal: Goals, db: Session = Depends(connect)):
    db_goal = db.query(Goals).filter(Goals.id == goal_id).first()
    if not db_goal:
        raise HTTPException(status_code=404, detail="Goal not found")
    for key, value in goal.dict().items():
        setattr(db_goal, key, value)
    db.commit()
    db.refresh(db_goal)
    return JSONResponse(content={"state": "ok", "data": db_goal})

@router.delete("/overview/goals/{goal_id}", response_model=GoalsResponse)
def delete_goal(goal_id: int, db: Session = Depends(connect)):
    db_goal = db.query(Goals).filter(Goals.id == goal_id).first()
    if not db_goal:
        raise HTTPException(status_code=404, detail="Goal not found")
    db.delete(db_goal)
    db.commit()
    return JSONResponse(content={"state": "ok", "data": db_goal})
